#!/usr/bin/env python3
"""
Empirical survey of the abelian ladder over honest prime numbers
================================================================

The theory predicts, for the maximal real subfield of the f-th cyclotomic field
with f = 2q + 1 prime and q prime:

  * a prime p splits completely exactly when p = +/-1 (mod f);
  * the split density among primes is 1/q, and the type entropy is
        H(T_q) = log2 q - ((q-1)/q) log2 (q-1);
  * the residue class channel is fully pinned: knowing p mod f leaves zero
    residual uncertainty about the splitting type;
  * for a semiprime N = p1 p2 the number of split factors follows Bin(2, 1/q).

This script sieves real primes, measures all four quantities empirically, and
compares them with the exact predictions.  Everything is standard library only.
"""

from __future__ import annotations

from math import gcd, log2
from typing import Dict, List, Tuple


def sieve(limit: int) -> List[int]:
    """All primes below `limit` by a simple sieve of Eratosthenes."""
    flags: List[bool] = [True] * limit
    flags[0] = flags[1] = False
    for i in range(2, int(limit ** 0.5) + 1):
        if flags[i]:
            for j in range(i * i, limit, i):
                flags[j] = False
    return [i for i, ok in enumerate(flags) if ok]


def real_residue_degree(f: int, u: int) -> int:
    """Order of u in (Z/f)^x / {+-1}: the residue degree in the real subfield."""
    power, order = u % f, 1
    while power != 1 % f and power != (f - 1) % f:
        power = (power * u) % f
        order += 1
    return order


def type_entropy(q: int) -> float:
    return log2(q) - ((q - 1) / q) * log2(q - 1)


def empirical_entropy(counts: Dict[int, int]) -> float:
    total = sum(counts.values())
    return -sum((c / total) * log2(c / total) for c in counts.values() if c)


def survey(f: int, q: int, primes: List[int]) -> Tuple[float, float, float, bool]:
    """Return (empirical split density, empirical entropy, conditional entropy, law holds)."""
    counts: Dict[int, int] = {}
    per_class: Dict[int, Dict[int, int]] = {}
    law_holds: bool = True
    for p in primes:
        if p == f or gcd(p, f) != 1:
            continue
        r = p % f
        d = real_residue_degree(f, r)
        counts[d] = counts.get(d, 0) + 1
        per_class.setdefault(r, {})
        per_class[r][d] = per_class[r].get(d, 0) + 1
        if (d == 1) != (r == 1 or r == f - 1):
            law_holds = False
    total = sum(counts.values())
    density = counts.get(1, 0) / total
    # conditional entropy of the type given the residue class
    cond = sum(
        (sum(hist.values()) / total) * empirical_entropy(hist) for hist in per_class.values()
    )
    return density, empirical_entropy(counts), cond, law_holds


def semiprime_split_counts(f: int, primes: List[int], samples: int) -> Dict[int, int]:
    """Split-count histogram over the first `samples` consecutive prime pairs."""
    usable = [p for p in primes if gcd(p, f) == 1]
    hist: Dict[int, int] = {0: 0, 1: 0, 2: 0}
    for i in range(min(samples, len(usable) // 2)):
        p1, p2 = usable[2 * i], usable[2 * i + 1]
        s = sum(1 for p in (p1, p2) if real_residue_degree(f, p % f) == 1)
        hist[s] += 1
    return hist


def main() -> None:
    primes = sieve(400_000)
    print(f"sieved {len(primes)} primes below 400000\n")
    header = f"{'q':>4} {'f':>4} {'split density':>15} {'1/q':>10} {'H empirical':>13} {'H exact':>10} {'H(T|class)':>12} {'law':>5}"
    print(header)
    print("-" * len(header))
    for q, f in ((2, 5), (3, 7), (5, 11), (11, 23), (23, 47), (29, 59), (41, 83), (53, 107)):
        density, h_emp, cond, law = survey(f, q, primes)
        print(
            f"{q:4d} {f:4d} {density:15.6f} {1/q:10.6f} {h_emp:13.6f} "
            f"{type_entropy(q):10.6f} {cond:12.9f} {str(law):>5}"
        )
    print("\nThe conditional entropy column is identically zero: full pinning, at every rung.")

    print("\nSemiprime split counts at degree 11 (conductor 23), 5000 consecutive prime pairs:")
    hist = semiprime_split_counts(23, primes, 5000)
    total = sum(hist.values())
    predicted = {0: (10 / 11) ** 2, 1: 2 * (10 / 11) * (1 / 11), 2: (1 / 11) ** 2}
    for s in (0, 1, 2):
        print(
            f"    {s} split factor(s): observed {hist[s]/total:.5f}   "
            f"Bin(2,1/11) predicts {predicted[s]:.5f}"
        )
    chi2 = sum((hist[s] - total * predicted[s]) ** 2 / (total * predicted[s]) for s in (0, 1, 2))
    print(f"    chi-square statistic (2 degrees of freedom): {chi2:.3f}")


if __name__ == "__main__":
    main()

