function REAL-RESIDUE-DEGREE(f, u):
    require gcd(u, f) = 1                      # otherwise the prime ramifies
    power <- u mod f
    order <- 1
    while power != 1 (mod f) and power != -1 (mod f):
        power <- (power * u) mod f
        order <- order + 1
    return order

function RUNG-PROFILE(f):
    U <- { u in [1, f-1] : gcd(u, f) = 1 }
    degree <- |U| / 2
    histogram <- empty map
    for u in U:
        d <- REAL-RESIDUE-DEGREE(f, u)
        histogram[d] <- histogram[d] + 1
    return (degree, histogram, histogram[1] / |U|)   # last entry is the split density

function COUNTING-ENTROPY(S, g):
    counts <- multiset of g(x) for x in S
    return - sum over values v of (counts[v]/|S|) * log2(counts[v]/|S|)

function CONDITIONAL-ENTROPY(S, g, k):
    partition S into fibres F_c = { x : k(x) = c }
    return sum over c of (|F_c| / |S|) * COUNTING-ENTROPY(F_c, g)

function MUTUAL-INFORMATION(S, g, k):
    return COUNTING-ENTROPY(S, g) - CONDITIONAL-ENTROPY(S, g, k)

function PINNING-WITNESS(S, g, k):            # exact, rounding-free
    seen <- empty map from channel value to (representative, type)
    for x in S:
        c <- k(x); v <- g(x)
        if c in seen:
            (y, w) <- seen[c]
            if w != v: return (y, x)          # certificate of strict loss
        else: seen[c] <- (x, v)
    return NONE                                # pinned: I = H exactly

