"""Channel entropy calculus and the exact pinning test."""

from __future__ import annotations

from math import log2
from typing import Callable, Dict, Hashable, List, Optional, Sequence, Tuple


def counting_entropy(space: Sequence[Hashable], read_out: Callable[[Hashable], Hashable]) -> float:
    """Shannon entropy in bits of the push-forward of the uniform measure on `space`.

    Complexity: one pass, O(|space|) evaluations of `read_out` and O(|image|) memory.
    """
    n: int = len(space)
    if n == 0:
        return 0.0
    counts: Dict[Hashable, int] = {}
    for x in space:
        v = read_out(x)
        counts[v] = counts.get(v, 0) + 1
    return -sum((c / n) * log2(c / n) for c in counts.values())


def conditional_entropy(
    space: Sequence[Hashable],
    read_out: Callable[[Hashable], Hashable],
    channel: Callable[[Hashable], Hashable],
) -> float:
    """H(read_out | channel): the fibre-weighted average of fibre entropies."""
    n: int = len(space)
    fibres: Dict[Hashable, List[Hashable]] = {}
    for x in space:
        fibres.setdefault(channel(x), []).append(x)
    return sum((len(f) / n) * counting_entropy(f, read_out) for f in fibres.values())


def mutual_information(
    space: Sequence[Hashable],
    read_out: Callable[[Hashable], Hashable],
    channel: Callable[[Hashable], Hashable],
) -> float:
    """I(channel ; read_out) = H(read_out) - H(read_out | channel)."""
    return counting_entropy(space, read_out) - conditional_entropy(space, read_out, channel)


def pinning_witness(
    space: Sequence[Hashable],
    read_out: Callable[[Hashable], Hashable],
    channel: Callable[[Hashable], Hashable],
) -> Optional[Tuple[Hashable, Hashable]]:
    """Exact pinning test.

    Returns None when the channel determines the read-out (so the conditional
    entropy is exactly zero and the mutual information is the full entropy);
    otherwise returns an explicit merged pair (x, y) with channel(x) = channel(y)
    but read_out(x) != read_out(y), which certifies strict information loss.

    Complexity: O(|space|) with a dictionary keyed by channel values.
    """
    seen: Dict[Hashable, Tuple[Hashable, Hashable]] = {}
    for x in space:
        c, v = channel(x), read_out(x)
        if c in seen:
            witness, value = seen[c]
            if value != v:
                return (witness, x)
        else:
            seen[c] = (x, v)
    return None


def pinning_report(
    space: Sequence[Hashable],
    read_out: Callable[[Hashable], Hashable],
    channel: Callable[[Hashable], Hashable],
) -> str:
    """Combine the structural test with the numerical entropies."""
    h = counting_entropy(space, read_out)
    i = mutual_information(space, read_out, channel)
    w = pinning_witness(space, read_out, channel)
    if w is None:
        return f"PINNED   : I = H = {h:.6f} bits (conditional entropy exactly 0)"
    return (
        f"LOSSY    : I = {i:.6f} < H = {h:.6f} bits; "
        f"the channel merges {w[0]!r} (type {read_out(w[0])}) with {w[1]!r} (type {read_out(w[1])})"
    )

